const PuzzleBook = preload("res://scripts/puzzles.gd")


func _init() -> void:
	for size in [5, 6, 7]:
		var start := Time.get_ticks_msec()
		var unique := 0
		var fell_back := 0
		var worst := 0
		for index in range(15, 65):
			var one := Time.get_ticks_msec()
			var level: Dictionary = PuzzleBook.generate(index, size)
			worst = maxi(worst, Time.get_ticks_msec() - one)
			if int(level["size"]) != size:
				fell_back += 1
			elif PuzzleBook.count_solutions(level) == 1:
				unique += 1
		print("size %d: %d/50 unique, %d fell back, %d ms total, %d ms worst room" % [
			size, unique, fell_back, Time.get_ticks_msec() - start, worst
		])
	var first: Dictionary = PuzzleBook.generate(99, 6)
	var again: Dictionary = PuzzleBook.generate(99, 6)
	print("same index rebuilds same room: ", first["regions"] == again["regions"])
	print("sample room 20 regions: ", PuzzleBook.generate(20, 6)["regions"])
	print("sample room 20 solution: ", PuzzleBook.generate(20, 6)["solution"])
	quit()

